  <div className="import-card-head"><span className="import-card-icon"><Film size={18}/></span><div><strong title={job.name}>{job.name}</strong><span>{friendlyBytes(job.size)}{job.count>1?` · fichier ${job.index+1} sur ${job.count}`:''}{job.inPlace?' · utilisé sur place, sans copie':''}</span></div>{copying&&<IconButton icon={X} label="Annuler l’import" onClick={onCancel}/>}</div>
