     {panel==='media'&&<><button className="upload-zone" onClick={()=>uploadRef.current.click()}><Upload size={23}/><strong>Importez quelque chose</strong><span>Choisir des vidéos, audios ou images</span></button>{assets.map(a=><div className="media-card" key={a.id}>{a.thumbnail?<img src={a.thumbnail} alt={a.name}/>:<div className="media-audio"><AudioLines size={30}/></div>}<div><strong>{a.name}</strong><span>{clock(a.duration)} · {a.type==='image'?'Image':a.type==='video'?'Vidéo':'Audio'}</span><button onClick={()=>{const id=uid();change(c=>{c.layers||=[];c.layers.push({id,type:a.type,assetId:a.id,start:Math.min(time,Math.max(0,total-.1)),end:Math.max(.1,Math.min(total||5,time+(a.duration||5))),sourceStart:0,x:.05,y:.05,width:.45,height:.45,opacity:1,volume:a.type==='video'?0:1,zIndex:c.layers.length+1,fadeIn:0,fadeOut:0});});setSelectedLayer(id);setPanel('layout');}}>Ajouter en calque<Plus size={12}/></button>{a.type!=='image'&&<button onClick={()=>{change((c,p)=>{const n=emptyComposition(a.name.replace(/\.[^.]+$/,''),[a.id]);p.compositions.push(n);setCompositionId(n.id);});setTime(0);}}>Utiliser dans une nouvelle composition<ArrowUpRight size={12}/></button>}</div></div>)}</>}
     {panel==='record'&&<>{[{id:'screen',icon:Monitor,title:'Enregistrement d’écran',text:'Écran, fenêtre ou onglet'},{id:'camera',icon:Video,title:'Caméra',text:'Caméra et micro'},{id:'audio',icon:Mic,title:'Enregistrement vocal',text:'Micro uniquement'}].map(({id,icon:Icon,title,text})=><button key={id} className="record-option" onClick={()=>{setRecordMode(id);setModal('record');}}><Icon size={23}/><div><strong>{title}</strong><span>{text}</span></div><ChevronRight size={15}/></button>)}<div className="info-box"><ShieldCheck size={17}/><p>Votre navigateur demande l’autorisation avant d’enregistrer. Les enregistrements sont ajoutés à votre médiathèque locale.</p></div></>}
